window.docContents[12].resolve({"/Improper-integrals/#chapter-3":{"contents":"This chapter introduces LMLF's interface for improper integrals on a half-line with finitely many\nsingular points. It records ordinary one-sided convergence at every singularity: contributions from\nopposite sides are never allowed to cancel as a principal value.\n\nThroughout, E is a complete normed real vector space.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean","header":"3. Improper integrals","id":"/Improper-integrals/#chapter-3"}});